// Playlist: https://www.shadertoy.com/playlist/mfdGWj

// Recreating some illustrations from Eric Lengyel's "Projective Geometric Algebra Illuminated".

struct bivec3 {
    vec3 v;
    vec3 m;
};

// Computes the 4D trivector passing through the origin.
vec4 planeToTrivector(vec3 p, vec3 q, vec3 r) {
    vec4 trivec;
    trivec.xyz = cross(q - p, r - p); // plane normal
    trivec.w = -dot(trivec.xyz, p); // plane offset
    return trivec;
}

// between two vec2's, the wedge product returns area of a parallelogram
float wedge(vec2 a, vec2 b) {
    return (a.x*b.y - a.y*b.x);    
}

// the antiwedge product is the negation of the wedge product
float antiwedge(vec2 a, vec2 b) {
    return -wedge(a, b);
}

// Returns the line where planes g and h meet.
bivec3 meetPlanes(vec4 g, vec4 h) {
    // g V h = (g.z*h.y - g.y*h.z) * e41 + (g.x*h.w - g.w * h.x)*e23 
    //       + (g.x*h.z - g.z*h.x) * e42 + (g.y*h.w - g.w * h.y)*e31
    //       + (g.y*h.x - g.x*h.y) * e43 + (g.z*h.w - g.w * h.z)*e12; 
    bivec3 line;
    line.v = vec3(antiwedge(g.yz, h.yz), antiwedge(g.zx, h.zx), antiwedge(g.xy, h.xy));
    line.m = vec3(antiwedge(g.wx, h.wx), antiwedge(g.wy, h.wy), antiwedge(g.wz, h.wz));
    return line;
}

#define OUTLINE_OUTER_WIDTH .03
#define OUTLINE_INNER_WIDTH .015

#define M2PI 6.28318530718

#if HW_PERFORMANCE==0
#define AA 1
#else
#define AA 2   // make this 2 or 3 for antialiasing
#endif

struct Payload {
    float d; // distance
    vec3 albedo; // albedo
};

const float lineThickness = .005;
const float arrowThickness = .01;
const float arrowCapWidth = .06;
const float arrowCapHeight = .12;

const float xLength = 2.0;
const float yLength = 2.0;
const float wLength = 2.0;
const float wPlaneHeight = 1.0;

void getGPlane(out vec3 p, out vec3 q, out vec3 r) {
    p = vec3(-sin(iTime * .7), -1.2, wPlaneHeight) + vec3(sin(iTime), 0.0, cos(iTime));
    q = -2.*vec3(sin(iTime), 0.0, cos(iTime)) + p;
    r = vec3(2.*sin(iTime * .7), 1.2+yLength, 0.0) + p;
}

void getHPlane(out vec3 p, out vec3 q, out vec3 r) {
    p = vec3(-1.2, -1.2, wPlaneHeight);
    q = vec3(1.2 + xLength, 0.0, 0.0) + p;
    r = vec3(0.0, 1.2 + yLength, 0.0) + p;
}

Payload map(in vec3 ro, vec3 rd) {
    Payload res;
    res.d = 1e38f;
    res.albedo = vec3(0.0);

    // H plane
    vec3 hp, hq, hr;
    getHPlane(hp, hq, hr);
    vec4 h = planeToTrivector(hp, hq, hr);

    // G Plane
    vec3 gp, gq, gr;
    getGPlane(gp, gq, gr);
    vec4 g = planeToTrivector(gp, gq, gr);

    // H plane outline
    {        
        // Opaque outline
        float d = 1e38f;
        d = min(d, sdCapsule( ro, hp, hq, 0.0 ));
        d = min(d, sdCapsule( ro, hq, hq + (hr - hp), 0.0 ));
        d = min(d, sdCapsule( ro, hq + (hr - hp), hr, 0.0 )); 
        d = min(d, sdCapsule( ro, hr, hp, 0.0 ));
        if (d < res.d) {res.d = d; res.albedo = vec3(0.0, 0.0, 0.0);}
    }

    // G plane outline
    {        
        // Opaque outline
        float d = 1e38f;
        d = min(d, sdCapsule( ro, gp, gq, 0.0 ));
        d = min(d, sdCapsule( ro, gq, gq + (gr - gp), 0.0 ));
        d = min(d, sdCapsule( ro, gq + (gr - gp), gr, 0.0 )); 
        d = min(d, sdCapsule( ro, gr, gp, 0.0 ));
        if (d < res.d) {res.d = d; res.albedo = vec3(0.0, 0.0, 0.0);}
    }

    // Meet the two planes together
    bivec3 line = meetPlanes(g, h);

    // Reinterpreting the above 4D bivector as a dual line in 3D,
    // we should see an arrow where the two planes meet.
    {
        vec3 p = cross(line.v, line.m) / dot(line.v, line.v);        
        vec3 dir = normalize(line.v);
        if (dir.y < 0.0) dir = -dir;

        vec3 start = p - 1.5 * dir;
        vec3 stop = p + 2.5 * dir;
        float d = sdArrow(ro, start, stop, arrowThickness, arrowCapWidth, arrowCapHeight*1.1);
        if (d < res.d) {res.d = d; res.albedo = emerald;}
    }

    return res;
}

vec4 over(vec4 a, vec4 b) {
  vec4 result;
  result.a = a.a + b.a * (1.f - a.a);
  if (result.a == 0.f)
    return a;   // avoid NaN
  result.rgb = (a.rgb * a.a + b.rgb * b.a * (1.f - a.a)) / result.a;
  return result;
}

vec3 scene(in vec3 ro,in vec3 rd) {
    vec3 col = vec3(1.0);		// initialize color return value

    vec3 roStart = ro;

    #define NHITS 3
    vec4 tuvs[NHITS];

    for (int i = 0; i < NHITS; ++i) tuvs[i].xw = vec2(1e38f, i);

    {
        vec3 hp, hq, hr;
        getHPlane(hp, hq, hr);

        vec3 gp, gq, gr;
        getGPlane(gp, gq, gr);

        // H plane
        tuvs[0].xyz = parallelogramIntersect(ro, rd, hp, hq, hr );        

        // G Plane
        tuvs[1].xyz = parallelogramIntersect(ro, rd, gp, gq, gr);
    }

    Payload payload;

    float rm = 1e38f; 			// tracker for minimum ray value
    float tmin = 15.0;
    float tmax = 23.0;
    float t = tmin;
    ro = roStart + t * rd;

    float totalW = OUTLINE_OUTER_WIDTH + OUTLINE_INNER_WIDTH;

    for (int i =0; i<128; i++) {
        payload = map(ro, rd);
        rm = min(payload.d, rm);

        //check if a ray has passed through an outline region
        if (payload.d > rm && rm < OUTLINE_OUTER_WIDTH) {
            col = vec3(0); //outline
            break;
        }

        if (payload.d < OUTLINE_INNER_WIDTH) {
            //color based on suface location
            col = payload.albedo;
            break;
        }


        t += max(payload.d - totalW, totalW*.1);
       	ro = roStart + t * rd;//*0.85;
        if (t > tmax) break;
    }

    tuvs[NHITS-1].x = t;

    vec4 bgcol = vec4(col, 1.0);

    // Sort by hit depth
    for (int i = 0; i < NHITS-1; ++i) {
        for (int j = 0; j < NHITS-1; ++j) {
            if (tuvs[j].x < tuvs[j+1].x) {
                vec4 tmp = tuvs[j];
                tuvs[j] = tuvs[j+1];
                tuvs[j+1] = tmp;
            }
        }
    }

    // Composite the W=1 plane
    vec4 rgba = vec4(1.0, 1.0, 1.0, .0);
    for (int i = 0; i < NHITS; ++i) {
        if( tuvs[i].x>0.0)
        {
            vec4 geoCol;
            if (tuvs[i].w == 0.0) geoCol = vec4(lightGray, .8);
            else if (tuvs[i].w == float(NHITS-1)) geoCol = vec4(col, 1.0);
            else geoCol = vec4(green, .7);            
            rgba = over(geoCol, rgba);
        }
    }

    return rgba.rgb;
}

mat3 lookAt(in vec3 eye, in vec3 tar, in float r){
    vec3 cw = normalize(tar - eye);// camera w
    vec3 cp = vec3(sin(r), 0.5, cos(r));// camera up
    vec3 cu = normalize(cross(cw, cp));// camera u
    vec3 cv = normalize(cross(cu, cw));// camera v
    return mat3(cu, cv, cw);
}


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec3 tot = vec3(0.0);

    // camera
    float an = .2;//-0.05*iTime -5.0*iMouse.x/iResolution.x;

    float dist = 20.f;
    float fov = 5.f;


    vec3  ro = dist * vec3(cos(3.0*an),sin(3.0*an), .3);
    vec3  ta = vec3(0.0,0.4,4./6.0);

    // camera matrix
    vec3 ww = normalize( ta - ro );
    vec3 uu = normalize( cross(ww,vec3(0.0,0.0,1.0) ) );
    vec3 vv = normalize( cross(uu,ww));

    for( int m=0; m<AA; m++ )
    for( int n=0; n<AA; n++ )
    {           
        //create p for ray based on AA settings
        vec3 p = vec3((-iResolution.xy + 2.0*(fragCoord.xy-0.5+(vec2(float(m),float(n))+0.5)/float(AA))) / iResolution.y,2.0);


        //create view ray from vector p
        vec3 rd = lookAt(ro, ta, 0.)*normalize(vec3(p.xy, 1.0/radians(fov)));// ray direction

        //render scene
        vec3 col = scene(ro,rd);

        //vignette
        //col -= 0.2*length(p.xy);

        tot += col;
    }
    tot /= float(AA*AA);
    fragColor = vec4( tot, 1.0 );
}

const vec3 black = vec3(0.)/255.;
const vec3 white = vec3(255.)/255.;
const vec3 lightGray = vec3(205.)/255.;
const vec3 mediumGray = vec3(140.)/255.;
const vec3 darkGray = vec3(94.)/255.;

const vec3 green = vec3(118., 185.,0.)/255.;
const vec3 emerald = vec3(0.,133.,100.)/255.;
const vec3 blue = vec3(0.,113.,197.)/255.;
const vec3 purple = vec3(93.,22.,130.)/255.;
const vec3 yellow = vec3(250.,194.,0.)/255.;
const vec3 garnet = vec3(137.,12.,88.)/255.;

vec3 parallelogramIntersect( in vec3 ro, in vec3 rd, in vec3 v0, in vec3 v1, in vec3 v2 )
{
    vec3 a = v0 - v1;
    vec3 b = v2 - v0;
    vec3 p = v0 - ro;

    vec3 n = cross( a, b );
    vec3 q = cross( rd, p );

    float i = 1.0/dot( rd, n );

    float u = dot( q, a )*i;
    float v = dot( q, b )*i;
    float t = dot( n, p )*i;

    if( u<0.0 || u>1.0 || v<0.0 || v>1.0 ) return vec3(-1.0);

    return vec3( t, u, v );
}

